package com.gittexplorer.documentextractor.validation;
import com.gittexplorer.documentextractor.configuration.DocumentExtractionProperties;import com.gittexplorer.documentextractor.exception.InvalidUploadException;import com.gittexplorer.documentextractor.exception.UnsupportedDocumentTypeException;import com.gittexplorer.documentextractor.util.FileNameUtility;import java.util.Arrays;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;
@Service public class FileValidationServiceImpl implements FileValidationService { private final DocumentExtractionProperties props; private final FileNameUtility names; public FileValidationServiceImpl(DocumentExtractionProperties props,FileNameUtility names){this.props=props;this.names=names;} public void validate(MultipartFile[] files){if(files==null||files.length==0)throw new InvalidUploadException("At least one file is required");long total=0;for(MultipartFile f:files){if(f==null)throw new InvalidUploadException("File must not be null");if(f.isEmpty())throw new InvalidUploadException("File is empty: "+f.getOriginalFilename());if(f.getSize()>props.getMaxFileSize().toBytes())throw new InvalidUploadException("File exceeds maximum size: "+f.getOriginalFilename());total+=f.getSize();}if(total>props.getMaxRequestSize().toBytes())throw new InvalidUploadException("Combined upload size exceeds maximum request size");}
 public void validateSupported(String fileName,String mimeType){String ext=names.extensionOf(fileName);boolean extOk=props.getSupportedExtensions().contains(ext);boolean mimeOk=props.getSupportedMimeTypes().contains(mimeType);if(!extOk&&!mimeOk)throw new UnsupportedDocumentTypeException("Unsupported file type: "+fileName+" ("+mimeType+")");} }
